/** The AbortSignal of the active turn, for operator prompts that must unblock on cancellation. */
public getActiveTurnSignal(): AbortSignal | undefined {
  return this.activeTurn?.controller.signal;
}

async runTurn(taskPrompt: string | any[], onConfirm?: ConfirmHandler, options?: { signal?: AbortSignal; resume?: boolean; tddRed?: boolean; step?: boolean }): Promise<TurnResult> {
  const ownsWorktreeDelegation = this.config.worktree && !this.worktreeRunTurnAuthorized;
  const delegatedWorktreeCall = this.worktreeRunTurnAuthorized && this.worktreeDelegatedTurnInProgress;
  const span = delegatedWorktreeCall ? undefined : this.safeStartTraceSpan("nexus.agent.turn", { "nexus.task.id": this.currentTaskId });
  const previousParent = this.activeTraceSpanId;
  if (span) {
    this.activeTraceSpanId = span.spanId;
  }
  if (ownsWorktreeDelegation) this.worktreeDelegatedTurnInProgress = true;
  let result: TurnResult | undefined;
  try {
    result = await this.runTurnImpl(taskPrompt, onConfirm, options);
    return result;
  } finally {
    if (result) {
      this.safeEndTraceSpan(span, this.traceStatusForExecution(result.execution), {
        "nexus.turn.execution": result.execution,
        "nexus.turn.outcome": result.outcome,
      });
    } else {
      this.safeEndTraceSpan(span, "error", {
        "nexus.turn.execution": "FAILED",
        "nexus.turn.outcome": "NOT_ESTABLISHED",
      });
    }
    this.activeTraceSpanId = previousParent;
    if (ownsWorktreeDelegation) this.worktreeDelegatedTurnInProgress = false;
  }
}

private async runTurnImpl(taskPrompt: string | any[], onConfirm?: ConfirmHandler, options?: { signal?: AbortSignal; resume?: boolean; tddRed?: boolean; step?: boolean }): Promise<TurnResult> {
  // The REPL calls runTurn directly. Route worktree-enabled turns through the
  // same establishment and resolution boundary as one-shot `run` tasks. A retained
  // named worktree is where the session keeps working; `run` reuses it.
  if (this.config.worktree && this.activeWorktree && this.activeWorktree.kind !== "named" && !this.worktreeRunTurnAuthorized) {
    throw new Error(`Cannot start a new task: unresolved worktree ${this.activeWorktree.taskId}; merge or discard it first.`);
  }
  if (this.config.worktree && !this.worktreeRunTurnAuthorized) {
    return await this.run(taskPrompt, onConfirm, options);
  }
  if (!this.config.worktree) this.assertNamedBindingCurrent();
  if (this.activeTurn) throw new Error("A turn is already active; wait for it to finish or cancel it.");
  const authoritativeVerifier = this.config.authoritativeVerifierCommand?.trim();
  if (authoritativeVerifier && this.changeBaseline === undefined) {
    // Capture workspace-resolved operator verifier files before plugins or the model can change them.
    // Existing pending work without an earlier snapshot remains unverified rather than being blessed retroactively.
    // A linked worktree the agent already worked in (an earlier session, another terminal) gives a baseline taken from
    // files the agent may have rewritten: verification proceeds as usual, but no receipt is issued on that baseline.
    this.judgeReceiptBaselineOnce();
    this.changeBaseline = {
      command: authoritativeVerifier,
      failed: false,
      tests: this.hasPendingModifications ? null : snapshotTests(this.config.workspace),
      verifier: this.hasPendingModifications ? null : snapshotVerifierDefinition(this.config.workspace, authoritativeVerifier, this.config.trustedDeliverableFiles ?? []),
      trustedDeliverables: [...(this.config.trustedDeliverableFiles ?? [])],
      at: new Date().toISOString(),
    };
    if (this.durable) {
      try {
        this.checkpointDurableState("authoritative verifier definition captured");
      } catch (err: any) {
        this.reportPersistenceFailure("baseline", err);
      }
    }

